import {confirmDelete} from './confirm-delete.js?v=e1d9f1be5a95';
import {createLock,emptyLockedNotes,sealNotes,unlockNotes,validPassword} from './locked-crypto.mjs?v=e1d9f1be5a95';
export function mountLocked(root,store){
 const confirmController=new AbortController();
 const wrapper=document.createElement('aside');wrapper.className='locked-area';
 wrapper.innerHTML=`<button type="button" id="locked-toggle" aria-expanded="false" aria-controls="locked-panel">LOCKED NOTES ⌃</button><section id="locked-panel" aria-label="Locked notes" hidden><header><strong>LOCKED NOTES</strong><button type="button" class="locked-close" aria-label="Close and lock notes">×</button></header><form class="locked-login"><label class="sr-only" for="locked-password">Password</label><input id="locked-password" type="password" minlength="1" maxlength="1024" placeholder="PASSWORD" autocomplete="off" required><button type="submit" class="locked-open">OPEN</button></form><div class="locked-content" hidden><div class="locked-tabs-row"><div class="locked-tabs" role="tablist" aria-label="Note sections"></div><button type="button" class="locked-add" aria-label="Add section">+</button></div><textarea id="locked-text" spellcheck="false" aria-label="Locked notes section 1"></textarea><div class="locked-actions"><button type="button" class="locked-password-toggle" aria-expanded="false">CHANGE PASSWORD</button><button type="button" class="locked-delete">DELETE NOTE</button></div><form class="locked-change-form" hidden><label class="sr-only" for="locked-old-password">Old password</label><input id="locked-old-password" type="password" minlength="1" maxlength="1024" placeholder="OLD PASSWORD" autocomplete="off" required><label class="sr-only" for="locked-new-password">New password</label><input id="locked-new-password" type="password" minlength="1" maxlength="1024" placeholder="NEW PASSWORD" autocomplete="off" required><button type="submit">CHANGE</button></form></div><p class="locked-status" role="status"></p></section>`;
 (root.querySelector('.note-tools')||root).append(wrapper);
 const $=s=>wrapper.querySelector(s),toggle=$('#locked-toggle'),panel=$('#locked-panel'),login=$('.locked-login'),password=$('#locked-password'),content=$('.locked-content'),text=$('#locked-text'),tabs=$('.locked-tabs'),changeForm=$('.locked-change-form');
 let cloud={value:null,revision:-1,ready:false,error:''},data=null,lock=null,revision=-1,selected=null,dirty=0,saved=0,busy=false,closing=false,disposed=false,token=0,timer,pendingSave=null;
 const status=message=>{if(!disposed)$('.locked-status').textContent=message;};
 function startAtTop(focus=false){
  const session=token,section=selected;
  text.setSelectionRange(0,0);if(focus)text.focus({preventScroll:true});
  text.scrollTop=0;text.scrollLeft=0;panel.scrollTop=0;
  requestAnimationFrame(()=>{if(!disposed&&session===token&&section===selected&&!panel.hidden&&text.selectionStart===0&&text.selectionEnd===0){text.scrollTop=0;text.scrollLeft=0;panel.scrollTop=0;}});
 }
 function controls(){if(disposed)return;toggle.disabled=closing;password.disabled=busy||!cloud.ready;$('.locked-open').disabled=busy||!cloud.ready;$('.locked-open').textContent=cloud.value?'OPEN':'SET PASSWORD';text.disabled=busy||closing;$('.locked-add').disabled=busy||closing||!data||data.tabs.length>=100;for(const input of changeForm.querySelectorAll('input,button'))input.disabled=busy||closing;$('.locked-password-toggle').disabled=busy||closing;$('.locked-delete').disabled=busy||closing||!data;$('.locked-close').disabled=busy||closing;for(const b of tabs.children)b.disabled=busy||closing;}
 function renderTabs(){tabs.replaceChildren();if(!data)return;data.tabs.forEach((tab,index)=>{const b=document.createElement('button');b.type='button';b.role='tab';b.textContent=index+1;b.dataset.id=tab.id;b.id='locked-tab-'+tab.id;b.setAttribute('aria-selected',String(tab.id===selected));b.setAttribute('aria-controls','locked-text');b.setAttribute('aria-label','Section '+(index+1));tabs.append(b);});const index=data.tabs.findIndex(t=>t.id===selected);text.setAttribute('aria-label','Locked notes section '+(index+1));text.setAttribute('aria-labelledby','locked-tab-'+selected);controls();}
 function wipe(){++token;clearTimeout(timer);data=lock=null;revision=-1;selected=null;dirty=saved=0;password.value=text.value=$('#locked-old-password').value=$('#locked-new-password').value='';tabs.replaceChildren();content.hidden=true;login.hidden=false;changeForm.hidden=true;$('.locked-password-toggle').setAttribute('aria-expanded','false');}
 function changed(){dirty++;status('SAVING…');clearTimeout(timer);timer=setTimeout(()=>flush().catch(e=>status(e.message)),600);}
 function flush(){
  clearTimeout(timer);if(pendingSave)return pendingSave;if(!lock||!data||dirty===saved)return Promise.resolve();const session=token;
  pendingSave=(async()=>{while(!disposed&&session===token&&lock&&dirty!==saved){const version=dirty,copy=structuredClone(data),envelope=await sealNotes(copy,lock,store.uid);if(disposed||session!==token)return;const next=await store.save(envelope,revision);if(disposed||session!==token)return;revision=next;saved=version;}if(!disposed&&session===token)status('SAVED');})().finally(()=>{pendingSave=null;if(!disposed&&lock&&cloud.revision>revision)status('NOTES CHANGED ON ANOTHER DEVICE. CLOSE AND REOPEN.');});return pendingSave;
 }
 async function close(){if(panel.hidden||busy||closing)return;closing=true;controls();try{await flush();if(disposed)return;wipe();panel.hidden=true;toggle.setAttribute('aria-expanded','false');status('');}catch(e){status(e.message);}finally{closing=false;controls();}}
 toggle.addEventListener('click',()=>{if(!panel.hidden){close();return;}panel.hidden=false;panel.scrollTop=0;toggle.setAttribute('aria-expanded','true');status(cloud.error||'');controls();password.focus({preventScroll:true});});
 $('.locked-close').addEventListener('click',close);
 login.addEventListener('submit',async event=>{
  event.preventDefault();if(busy||!cloud.ready||!validPassword(password.value))return;busy=true;controls();status('OPENING…');const session=token,existing=cloud.value,expected=cloud.revision,secret=password.value;password.value='';
  try{let result;if(existing)result=await unlockNotes(existing,secret,store.uid);else {const nextLock=await createLock(secret),nextData=emptyLockedNotes(),envelope=await sealNotes(nextData,nextLock,store.uid);if(disposed||session!==token)return;const next=await store.save(envelope,expected);result={lock:nextLock,data:nextData};revision=next;}
   if(disposed||session!==token)return;if(existing&&cloud.revision!==expected)throw Error('NOTES CHANGED. TRY AGAIN.');
   lock=result.lock;data=result.data;if(existing)revision=expected;selected=data.tabs[0].id;dirty=saved=0;login.hidden=true;content.hidden=false;text.value=data.tabs[0].text;renderTabs();status('SAVED');
  }catch(e){status(e.message);}finally{busy=false;controls();if(!disposed&&!panel.hidden){if(lock)startAtTop(true);else password.focus({preventScroll:true});}}
 });
 text.addEventListener('input',()=>{if(!data||!lock)return;const tab=data.tabs.find(t=>t.id===selected);if(tab){tab.text=text.value;changed();}});
 tabs.addEventListener('click',event=>{const button=event.target.closest('[data-id]');if(!button||busy||closing||!data)return;selected=button.dataset.id;text.value=data.tabs.find(t=>t.id===selected).text;renderTabs();startAtTop(true);});
 tabs.addEventListener('keydown',event=>{if(!data||!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const current=data.tabs.findIndex(t=>t.id===selected),index=event.key==='Home'?0:event.key==='End'?data.tabs.length-1:(current+(event.key==='ArrowRight'?1:-1)+data.tabs.length)%data.tabs.length;selected=data.tabs[index].id;text.value=data.tabs[index].text;renderTabs();startAtTop();tabs.children[index]?.focus({preventScroll:true});});
 $('.locked-add').addEventListener('click',()=>{if(!data||busy||closing||data.tabs.length>=100)return;const tab={id:crypto.randomUUID(),text:''};data.tabs.push(tab);selected=tab.id;text.value='';renderTabs();changed();startAtTop(true);});
 $('.locked-delete').addEventListener('click',async()=>{const session=token;if(!data||!lock||busy||closing)return;if(!await confirmDelete('DELETE THIS LOCKED NOTE SECTION?',confirmController.signal)||disposed||session!==token||!data||busy||closing)return;const index=data.tabs.findIndex(t=>t.id===selected);data.tabs.splice(index,1);if(!data.tabs.length)data.tabs.push({id:crypto.randomUUID(),text:''});selected=data.tabs[Math.min(index,data.tabs.length-1)].id;text.value=data.tabs.find(t=>t.id===selected).text;renderTabs();changed();startAtTop(true);});
 $('.locked-password-toggle').addEventListener('click',()=>{changeForm.hidden=!changeForm.hidden;$('.locked-password-toggle').setAttribute('aria-expanded',String(!changeForm.hidden));if(!changeForm.hidden)$('#locked-old-password').focus();else{$('#locked-old-password').value=$('#locked-new-password').value='';}});
 changeForm.addEventListener('submit',async event=>{
  event.preventDefault();if(busy||closing||!lock)return;const old=$('#locked-old-password').value,next=$('#locked-new-password').value;if(!validPassword(old)||!validPassword(next))return;
  busy=true;controls();status('SAVING…');const session=token;
  try{await flush();if(disposed||session!==token)return;await unlockNotes(cloud.value,old,store.uid);const nextLock=await createLock(next),envelope=await sealNotes(data,nextLock,store.uid);if(disposed||session!==token)return;const nextRevision=await store.save(envelope,revision);if(disposed||session!==token)return;lock=nextLock;revision=nextRevision;status('PASSWORD CHANGED');changeForm.hidden=true;$('.locked-password-toggle').setAttribute('aria-expanded','false');}
  catch(e){status(e.message);}finally{$('#locked-old-password').value=$('#locked-new-password').value='';busy=false;controls();}
 });
 const stop=store.subscribe(snapshot=>{cloud=snapshot;if(cloud.error)status(cloud.error);else if(lock&&!pendingSave&&!busy&&cloud.revision>revision)status('NOTES CHANGED ON ANOTHER DEVICE. CLOSE AND REOPEN.');controls();});
 const outside=event=>{if(!panel.hidden&&!event.composedPath().includes(wrapper))close();},escape=event=>{if(event.key==='Escape'&&!panel.hidden){event.preventDefault();close();}},visibility=event=>{if(event.detail===false)close();};document.addEventListener('click',outside);document.addEventListener('keydown',escape);window.addEventListener('temponotes-visibility',visibility);
 return ()=>{disposed=true;confirmController.abort();wipe();stop();document.removeEventListener('click',outside);document.removeEventListener('keydown',escape);window.removeEventListener('temponotes-visibility',visibility);wrapper.remove();};
}
